from fractions import Fraction


def causal_pairs_chunked(history, chunks, include_self=True):
    pairs = set()
    segments = []
    c = history
    for q in chunks:
        if q <= 0:
            raise ValueError('chunk sizes must be positive')
        count = 0
        for i in range(q):
            p = c + i
            end = p if include_self else p - 1
            for k in range(end + 1):
                pairs.add((p, k))
                count += 1
        segments.append(count)
        c += q
    return pairs, segments, c


def causal_pairs_full(history, total):
    pairs = set()
    for p in range(history, history + total):
        for k in range(p + 1):
            pairs.add((p, k))
    return pairs


def test_mask_equivalence():
    history = 5
    chunks = [2, 3, 1]
    total = sum(chunks)
    got, segments, end = causal_pairs_chunked(history, chunks)
    ref = causal_pairs_full(history, total)
    if got != ref:
        raise AssertionError('chunk mask differs from full causal mask')
    if end != history + total:
        raise AssertionError('final committed boundary is wrong')
    formula = (history + total) * (history + total + 1) // 2 - history * (history + 1) // 2
    if sum(segments) != formula:
        raise AssertionError('pair count formula mismatch')
    bad, bad_segments, _ = causal_pairs_chunked(history, chunks, include_self=False)
    if bad == ref:
        raise AssertionError('negative control accepted: self key removed')
    if len(bad) >= len(ref):
        raise AssertionError('negative control did not reduce pair count')
    print('mask_equivalence: full_pairs=%d segments=%s' % (len(ref), segments))
    print('mask_negative_control: removed_pairs=%d detected=yes' % (len(ref) - len(bad)))


def model_time(history, q, a, b, c):
    return a + b * q + c * (q * history + q * (q + 1) // 2)


def max_q_by_budget(history, budget, a, b, c):
    q = 0
    while model_time(history, q + 1, a, b, c) <= budget:
        q += 1
    return q


def model_time_bad(history, q, a, b, c):
    return a + b * q + c * q * history


def max_q_bad(history, budget, a, b, c):
    q = 0
    while model_time_bad(history, q + 1, a, b, c) <= budget:
        q += 1
    return q


def test_budget_solver():
    a = Fraction(2, 1)
    b = Fraction(1, 100)
    c = Fraction(1, 1000000)
    budget = Fraction(10, 1)
    q1 = max_q_by_budget(1000, budget, a, b, c)
    q2 = max_q_by_budget(7000, budget, a, b, c)
    if q1 != 704:
        raise AssertionError('h=1000 budget result mismatch: %s' % q1)
    if q2 != 464:
        raise AssertionError('h=7000 budget result mismatch: %s' % q2)
    bad_q = max_q_bad(1000, budget, a, b, c)
    if bad_q <= q1:
        raise AssertionError('negative control did not overestimate q')
    print('budget_solver: h1000_q=%d h7000_q=%d' % (q1, q2))
    print('budget_negative_control: omitted_triangular_q=%d detected=yes' % bad_q)


def page_increment(prefix, q, page):
    return (prefix + q + page - 1) // page - (prefix + page - 1) // page


def max_q_by_pages(prefix, free_pages, page):
    q = 0
    while page_increment(prefix, q + 1, page) <= free_pages:
        q += 1
    return q


def test_page_capacity():
    q = max_q_by_pages(1000, 4, 16)
    if q != 72:
        raise AssertionError('page capacity result mismatch: %s' % q)
    naive = 4 * 16
    if naive == q:
        raise AssertionError('negative control did not miss tail-page reuse')
    print('page_capacity: prefix=1000 page=16 free=4 q=%d' % q)
    print('page_negative_control: naive_tokens=%d detected=yes' % naive)


def equal_chunk_block_reads(history, total, n):
    if total % n != 0:
        raise ValueError('equal chunks require divisibility')
    q = total // n
    c = history
    reads = 0
    for _ in range(n):
        reads += c + q
        c += q
    return reads, q


def test_kv_reread_model():
    history = 1000
    total = 4096
    n = 4
    reads, q = equal_chunk_block_reads(history, total, n)
    full = history + total
    overhead = reads - full
    formula = (n - 1) * history + total * (n - 1) // 2
    if overhead != formula:
        raise AssertionError('kv reread formula mismatch')
    bad = (n - 1) * history
    if bad == overhead:
        raise AssertionError('negative control did not miss triangular reread')
    print('kv_reread: chunk_reads=%d full_reads=%d overhead=%d q=%d' % (reads, full, overhead, q))
    print('kv_negative_control: omitted_triangular=%d detected=yes' % bad)


def next_action(prompt_len, committed, has_logits):
    if prompt_len <= 0:
        return 'reject_empty_without_bos_contract'
    if committed < prompt_len:
        return 'prefill'
    if has_logits:
        return 'decode'
    return 'recover_last_query'


def naive_action(prompt_len, committed, has_logits):
    if committed < prompt_len:
        return 'prefill'
    return 'decode'


def test_recovery_boundary():
    if next_action(8, 8, False) != 'recover_last_query':
        raise AssertionError('missing-logits boundary not recovered')
    if next_action(8, 8, True) != 'decode':
        raise AssertionError('ready logits did not transition to decode')
    if next_action(8, 7, False) != 'prefill':
        raise AssertionError('ordinary suffix was not marked prefill')
    if next_action(0, 0, False) != 'reject_empty_without_bos_contract':
        raise AssertionError('empty prompt was not rejected')
    if naive_action(8, 8, False) == next_action(8, 8, False):
        raise AssertionError('negative control did not confuse recovery with decode')
    print('recovery_boundary: c=P,logits=false -> recover_last_query')
    print('recovery_negative_control: naive_recovery_is_decode detected=yes')


if __name__ == '__main__':
    test_mask_equivalence()
    test_budget_solver()
    test_page_capacity()
    test_kv_reread_model()
    test_recovery_boundary()
    print('PASS: CPU reference checks, boundary cases, and negative controls')
